package solution
import("strconv";"strings")
func MovingSums(s string)(string,bool){p:=strings.Split(s,";");if len(p)!=2||p[1]==""{return "",false};w,e:=strconv.Atoi(p[0]);if e!=nil||w<1||w>100000||strconv.Itoa(w)!=p[0]{return "",false};a:=[]int{};for _,x:=range strings.Split(p[1],","){v,e:=strconv.Atoi(x);if e!=nil||v<0||v>10000000||strconv.Itoa(v)!=x{return "",false};a=append(a,v)};if len(a)<w{return "",false};v:=0;for _,x:=range a[:w]{v+=x};if v>10000000{return "",false};o:=[]string{strconv.Itoa(v)};for i:=w;i<len(a);i++{v+=a[i]-a[i-w];if v>10000000{return "",false};o=append(o,strconv.Itoa(v))};return strings.Join(o,","),true}
